# ports.py - what the core needs (no boto3 / psycopg2 imports here)
from typing import Protocol, Callable
import pandas as pd

class FileStore(Protocol):
    def read(self, key: str) -> bytes: ...

class UploadRepo(Protocol):
    def set_status(self, upload_id: str, status: str, error: str | None = None) -> None: ...

class OrderRepo(Protocol):
    def upsert_many(self, df: pd.DataFrame) -> int: ...

# registry of strategies: report_type -> pure transform
Processor = Callable[[bytes], pd.DataFrame]
PROCESSORS: dict[str, Processor] = {}

def register(report_type: str):
    def deco(fn: Processor) -> Processor:
        PROCESSORS[report_type] = fn
        return fn
    return deco

@register("amazon_settlement")
def amazon_settlement(raw: bytes) -> pd.DataFrame:      # domain logic, no I/O
    import io
    df = pd.read_csv(io.BytesIO(raw), sep="\t", encoding="utf-8-sig")
    return df.rename(columns={"order-id": "order_id", "amount": "amount"})
