# service.py - the use case, depends only on ports
import logging
logger = logging.getLogger(__name__)

class UnknownReportType(Exception): ...

class UploadService:
    def __init__(self, files: FileStore, uploads: UploadRepo, orders: OrderRepo,
                 processors: dict[str, Processor] = PROCESSORS):
        self.files, self.uploads, self.orders, self.processors = files, uploads, orders, processors

    def process(self, upload_id: str, key: str, report_type: str) -> int:
        processor = self.processors.get(report_type)
        if processor is None:
            raise UnknownReportType(report_type)
        self.uploads.set_status(upload_id, "processing")
        try:
            n = self.orders.upsert_many(processor(self.files.read(key)))
        except Exception as e:
            logger.exception("upload failed upload_id=%s", upload_id)
            self.uploads.set_status(upload_id, "failed", error=repr(e))
            raise
        self.uploads.set_status(upload_id, "done")
        return n

# adapters.py - concrete edges
class S3FileStore:
    def __init__(self, client, bucket): self.client, self.bucket = client, bucket
    def read(self, key): return self.client.get_object(Bucket=self.bucket, Key=key)["Body"].read()

class PgOrderRepo:
    def __init__(self, transaction): self.transaction = transaction   # e.g. db_transaction()
    def upsert_many(self, df):
        with self.transaction() as cur:
            execute_values(cur, UPSERT_SQL, list(df.itertuples(index=False, name=None)))
            return len(df)

# main.py / handler - composition root
def handler(event, context):
    svc = UploadService(S3FileStore(boto3.client("s3"), BUCKET),
                        PgUploadRepo(db_transaction), PgOrderRepo(db_transaction))
    rec = event["Records"][0]
